{
  "conversations": [
    {
      "title": "Accept or decline a dance",
      "lines": [
        { "speaker": "partner", "text": "Would you like to dance?" },
        { "speaker": "you", "text": "I'd love to." },
        { "speaker": "you", "text": "I'm taking a break right now.", "or": true },
        { "speaker": "partner", "text": "No worries." },
        { "speaker": "partner", "text": "Maybe next song.", "or": true }
      ]
    },
    {
      "title": "Compliment someone's dancing",
      "lines": [
        { "speaker": "you", "text": "You're a great dancer." },
        { "speaker": "partner", "text": "Thank you so much." },
        { "speaker": "you", "text": "I like your style." },
        { "speaker": "partner", "text": "You're doing great too." },
        { "speaker": "you", "text": "Thanks for the dance." },
        { "speaker": "partner", "text": "My pleasure." }
      ]
    },
    {
      "title": "Chat between songs",
      "lines": [
        { "speaker": "partner", "text": "Do you come here often?" },
        { "speaker": "you", "text": "It's my first time here." },
        { "speaker": "partner", "text": "How do you like it?" },
        { "speaker": "you", "text": "I love the music." },
        { "speaker": "partner", "text": "It's a great band tonight." },
        { "speaker": "you", "text": "Really amazing." }
      ]
    }
  ]
}
